node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Find the user (self)
const self = db.prepare(\"SELECT * FROM ts_contacts WHERE is_self = 1\").all();
console.log('Self contact:', JSON.stringify(self, null, 2));

// Search for messages to +1-347-555-0169 on 2026-09-01 around 10:00 AM
const messages = db.prepare(\`
  SELECT m.*, 
         sc.name as sender_name, 
         rc.name as recipient_name
  FROM ts_messages m
  LEFT JOIN ts_contacts sc ON m.sender_person_id = sc.person_id
  LEFT JOIN ts_contacts rc ON m.recipient_person_id = rc.person_id
  WHERE m.recipient_phone_number LIKE '%347%555%0169%'
    AND m.created_at LIKE '2026-09-01%'
\`).all();
console.log('\\nMessages to +1-347-555-0169 on 2026-09-01:');
console.log(JSON.stringify(messages, null, 2));
"
